    hs,vs=find_seps(g)
    rg=[r for r in range(R) if r not in hs]
    cg=[c for c in range(C) if c not in vs]
    # group consecutive
    def groups(idx):
        out=[];cur=[]
        for i in idx:
            if cur and i==cur[-1]+1: cur.append(i)
            elif cur: out.append(cur);cur=[i]
            else: cur=[i]
        if cur: out.append(cur)
        return out
    rg=groups(rg); cg=groups(cg)
    return rg,cg

def region_of(rg,cg,r,c):
    return (next(i for i,gr in enumerate(rg) if r in gr), next(j for j,gc in enumerate(cg) if c in gc))

def markers_and_regions(g):
    rg,cg=regions(g)
    reg={}
