    from collections import Counter
    hs,vs=find_seps(g)
    sepcol = g[hs[0]][0] if hs else g[0][vs[0]]
    cnt=Counter(x for r in g for x in r if x!=sepcol)
    bg=cnt.most_common(1)[0][0]
    mk={}
    for r in range(len(g)):
        for c in range(len(g[0])):
